// Ban toi thieu (giai doan 3). Giai doan 6 them Telegram va chong bao loi.
const e = $json;
const redact = (s) => String(s ?? '')
  .replace(/\d{8,10}:[\w-]{35}/g, '<telegram-token>')
  .replace(/sk-[A-Za-z0-9_-]{10,}/g, '<api-key>')
  .replace(/Bearer\s+\S+/g, 'Bearer <redacted>');
return [{ json: {
  workflow: e.workflow?.name ?? '',
  node: e.execution?.lastNodeExecuted ?? '',
  message: redact(e.execution?.error?.message).slice(0, 500),
  at: DateTime.now().setZone('Asia/Ho_Chi_Minh').toISO({ suppressMilliseconds: true }),
  url: e.execution?.url ?? '',
} }];
